import{_ as t,c as a,o as n,a3 as o}from"./chunks/framework.Dk6sf0Ip.js";const m=JSON.parse('{"title":"Mantenimiento Detallado","description":"","frontmatter":{},"headers":[],"relativePath":"reportes/mantenimientoCubiertas/mantenimientosCubiertasDetalles.md","filePath":"reportes/mantenimientoCubiertas/mantenimientosCubiertasDetalles.md","lastUpdated":null}'),r={name:"reportes/mantenimientoCubiertas/mantenimientosCubiertasDetalles.md"};function i(l,e,s,d,c,g){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="mantenimiento-detallado" tabindex="-1">Mantenimiento Detallado <a class="header-anchor" href="#mantenimiento-detallado" aria-label="Permalink to &quot;Mantenimiento Detallado&quot;">​</a></h1><p>Este reporte brinda una visión completa de una única intervención de mantenimiento, desglosando el trabajo realizado, los costos, la posición de las cubiertas en la unidad y el movimiento de inventario de neumáticos.</p><h2 id="_1-datos-de-identificacion-esquina-superior-derecha" tabindex="-1">1. Datos de Identificación (Esquina Superior Derecha) <a class="header-anchor" href="#_1-datos-de-identificacion-esquina-superior-derecha" aria-label="Permalink to &quot;1. Datos de Identificación (Esquina Superior Derecha)&quot;">​</a></h2><p>Esta sección identifica la orden de trabajo específica y su contexto:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Campo</th><th style="text-align:left;">Significado / Interpretación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ORDEN</strong></td><td style="text-align:left;">El número único de la orden de trabajo (en este caso, <strong>443</strong>).</td></tr><tr><td style="text-align:left;"><strong>FECHA</strong></td><td style="text-align:left;">La fecha en que se realizó o registró el mantenimiento (en este caso, <strong>Sep 1, 2025</strong>).</td></tr><tr><td style="text-align:left;"><strong>GOMERIA</strong></td><td style="text-align:left;">El proveedor o taller que ejecutó el trabajo (en este caso, <strong>Gomería Axion</strong>).</td></tr><tr><td style="text-align:left;"><strong>Patente/Unidad</strong></td><td style="text-align:left;">El código o patente de la unidad a la que se le realizó el mantenimiento (en este caso, <strong>AE236PI</strong>).</td></tr></tbody></table><h2 id="_2-trabajo-realizado-izquierda" tabindex="-1">2. Trabajo Realizado (Izquierda) <a class="header-anchor" href="#_2-trabajo-realizado-izquierda" aria-label="Permalink to &quot;2. Trabajo Realizado (Izquierda)&quot;">​</a></h2><p>Detalla la tarea ejecutada y su costo:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Columna</th><th style="text-align:left;">Significado / Interpretación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>TRABAJO</strong></td><td style="text-align:left;">La descripción de la labor efectuada (en el ejemplo, <strong>ROTACION</strong>).</td></tr><tr><td style="text-align:left;"><strong>CANT.</strong></td><td style="text-align:left;">La cantidad de veces que se realizó ese trabajo o la cantidad de ítems relacionados.</td></tr><tr><td style="text-align:left;"><strong>IMPORTE</strong></td><td style="text-align:left;">El costo unitario de la tarea o el ítem (en el ejemplo, $15.000,0).</td></tr><tr><td style="text-align:left;"><strong>TOTAL</strong></td><td style="text-align:left;">El costo total de ese tipo de trabajo (Cantidad x Importe).</td></tr></tbody></table><h2 id="_3-posicion-de-cubiertas-derecha" tabindex="-1">3. Posición de Cubiertas (Derecha) <a class="header-anchor" href="#_3-posicion-de-cubiertas-derecha" aria-label="Permalink to &quot;3. Posición de Cubiertas (Derecha)&quot;">​</a></h2><p>Esta es una representación gráfica de los ejes y las posiciones de los neumáticos en la unidad (<strong>AE236PI</strong>).</p><ul><li><strong>Números (11, 13, 12, 14, etc.):</strong> Representan el número de <strong>posición</strong> del neumático en el vehículo (ejes, remolques, etc.).</li><li><strong>C / R:</strong><ul><li><strong>C</strong> = Posición <strong>C</strong>entral (o externa, dependiendo de la configuración del eje dual).</li><li><strong>R</strong> = Posición <strong>R</strong>emota (o interna, dependiendo de la configuración del eje dual).</li></ul></li><li><strong>Texto en las Casillas:</strong> Indica la <strong>identificación de la cubierta</strong> que fue colocada o que estaba en esa posición al momento del mantenimiento. <ul><li>Por ejemplo, en la posición 20-C está la cubierta <strong>MICHELIN ZCN34029A</strong>.</li><li>En la posición 20-R está la cubierta <strong>MICHELIN VCI20507A</strong>.</li></ul></li></ul><h2 id="_4-movimiento-de-inventario-inferior" tabindex="-1">4. Movimiento de Inventario (Inferior) <a class="header-anchor" href="#_4-movimiento-de-inventario-inferior" aria-label="Permalink to &quot;4. Movimiento de Inventario (Inferior)&quot;">​</a></h2><p>Esta sección es crucial para la gestión de inventario, ya que muestra qué cubiertas <strong>SALIERON</strong> de la unidad (o del stock general) y cuáles <strong>ENTRARON</strong> a la unidad (o al stock general).</p><h3 id="salida-sale" tabindex="-1">SALIDA (SALE) <a class="header-anchor" href="#salida-sale" aria-label="Permalink to &quot;SALIDA (SALE)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Columna</th><th style="text-align:left;">Significado / Interpretación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MARCA - CÓDIGO</strong></td><td style="text-align:left;">Marca y código de la cubierta que fue <strong>retirada</strong> del vehículo.</td></tr><tr><td style="text-align:left;"><strong>MODELO - FECHA - TIPO - MED</strong></td><td style="text-align:left;">Detalles de la cubierta (modelo, fecha de fabricación/montaje, tipo, y medida).</td></tr><tr><td style="text-align:left;"><strong>ESTADO</strong></td><td style="text-align:left;">El estado de la cubierta al ser retirada (en el ejemplo, <strong>PARA RECAPAR</strong>). Esto sugiere que fue a un proceso de reencauchado.</td></tr><tr><td style="text-align:left;"><strong>POSICION</strong></td><td style="text-align:left;">La posición de la que fue retirada (en el ejemplo, <strong>20</strong>).</td></tr></tbody></table><h3 id="entrada-entra" tabindex="-1">ENTRADA (ENTRA) <a class="header-anchor" href="#entrada-entra" aria-label="Permalink to &quot;ENTRADA (ENTRA)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Columna</th><th style="text-align:left;">Significado / Interpretación</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MARCA - CÓDIGO</strong></td><td style="text-align:left;">Marca y código de la cubierta que fue <strong>colocada</strong> en el vehículo.</td></tr><tr><td style="text-align:left;"><strong>MODELO - FECHA - TIPO - MED</strong></td><td style="text-align:left;">Detalles de la cubierta colocada.</td></tr><tr><td style="text-align:left;"><strong>ESTADO</strong></td><td style="text-align:left;">El estado de la cubierta al ser colocada (en el ejemplo, <strong>RECAPADA</strong>).</td></tr><tr><td style="text-align:left;"><strong>POSICION</strong></td><td style="text-align:left;">La posición en la que fue colocada (en el ejemplo, <strong>20</strong>).</td></tr></tbody></table><h2 id="resumen-del-evento-segun-el-ejemplo" tabindex="-1">Resumen del Evento (Según el Ejemplo) <a class="header-anchor" href="#resumen-del-evento-segun-el-ejemplo" aria-label="Permalink to &quot;Resumen del Evento (Según el Ejemplo)&quot;">​</a></h2><p>La orden <strong>443</strong> del <strong>1 de septiembre de 2025</strong> muestra una <strong>ROTACIÓN</strong> de $15.000 a la unidad <strong>AE236PI</strong>.</p><p>En el Eje 20, se retiró la cubierta <strong>MICHELIN VCI20507A</strong> (que estaba <strong>PARA RECAPAR</strong>) y se colocó la cubierta <strong>MICHELIN ZCN34025A</strong> (que ya estaba <strong>RECAPADA</strong>), indicando un <strong>cambio de cubierta</strong> en esa posición como parte del servicio.</p><h2 id="funciones-implicitas-del-reporte" tabindex="-1">Funciones Implícitas del Reporte <a class="header-anchor" href="#funciones-implicitas-del-reporte" aria-label="Permalink to &quot;Funciones Implícitas del Reporte&quot;">​</a></h2><ul><li><strong>Auditoría:</strong> Permite verificar que el trabajo facturado (ROTACIÓN) se corresponde con los movimientos de inventario y las posiciones actualizadas.</li><li><strong>Trazabilidad:</strong> Proporciona un registro claro de qué cubierta (por código) estuvo en qué posición, en qué fecha, y cuál fue su estado posterior.</li><li><strong>Inventario:</strong> Sirve como comprobante para actualizar el stock de cubiertas disponibles y las que están en proceso de recape.</li></ul>',22)]))}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
